"use client"

import * as React from "react"
import { cn } from "@/lib/utils"

/**
 * Generate superellipse path for SVG
 * Formula: |x/a|^n + |y/b|^n = 1
 *
 * @param n - Exponent (2 = ellipse, 4-5 = squircle, higher = more rectangular)
 * @param size - Size of the shape (100 for viewBox)
 * @param points - Number of points to generate (more = smoother)
 */
function generateSuperellipsePath(
  n: number = 5,
  size: number = 100,
  points: number = 360
): string {
  const a = size / 2
  const b = size / 2
  const cx = size / 2
  const cy = size / 2

  const pathPoints: string[] = []

  for (let i = 0; i <= points; i++) {
    const angle = (i / points) * 2 * Math.PI
    const cosA = Math.cos(angle)
    const sinA = Math.sin(angle)

    // Superellipse parametric equations
    const x = cx + a * Math.sign(cosA) * Math.pow(Math.abs(cosA), 2 / n)
    const y = cy + b * Math.sign(sinA) * Math.pow(Math.abs(sinA), 2 / n)

    if (i === 0) {
      pathPoints.push(`M ${x.toFixed(2)} ${y.toFixed(2)}`)
    } else {
      pathPoints.push(`L ${x.toFixed(2)} ${y.toFixed(2)}`)
    }
  }

  pathPoints.push("Z")
  return pathPoints.join(" ")
}

/**
 * Generate iOS-style squircle path (Apple uses approximately n=5)
 */
function generateSquirclePath(size: number = 100): string {
  return generateSuperellipsePath(5, size, 360)
}

/**
 * Create SVG data URL for clip-path
 */
function createSquircleSvgUrl(n: number = 5): string {
  const path = generateSuperellipsePath(n, 100, 360)
  const svg = `<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'><path d='${path}' fill='black'/></svg>`
  return `url("data:image/svg+xml,${encodeURIComponent(svg)}")`
}

// Pre-generated paths for common values (performance optimization)
const SQUIRCLE_PATH = generateSquirclePath(100)
const SQUIRCLE_CLIP_PATH = `path("${SQUIRCLE_PATH}")`

export interface SquircleProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Superellipse exponent: 2=ellipse, 5=squircle (Apple), higher=more square */
  n?: number
  /** Children elements */
  children?: React.ReactNode
}

/**
 * Squircle - iOS-style rounded rectangle with smooth continuous curves
 *
 * Uses SVG clip-path for cross-browser support. The shape is mathematically
 * accurate using the superellipse formula with n≈5 (Apple's iOS icon shape).
 *
 * @example
 * ```tsx
 * <Squircle className="w-32 h-32 bg-blue-500">
 *   <img src="..." alt="..." className="w-full h-full object-cover" />
 * </Squircle>
 * ```
 */
export function Squircle({
  className,
  style,
  n = 5,
  children,
  ...props
}: SquircleProps) {
  const clipPath = React.useMemo(() => {
    if (n === 5) return SQUIRCLE_CLIP_PATH
    const path = generateSuperellipsePath(n, 100, 360)
    return `path("${path}")`
  }, [n])

  return (
    <div
      className={cn("relative overflow-hidden", className)}
      style={{
        ...style,
        clipPath,
        // Fallback for browsers without clip-path: path()
        WebkitClipPath: clipPath,
      }}
      data-squircle
      data-n={n}
      {...props}
    >
      {children}
    </div>
  )
}

/**
 * SquircleImage - Optimized squircle specifically for images
 */
export interface SquircleImageProps
  extends React.ImgHTMLAttributes<HTMLImageElement> {
  /** Superellipse exponent */
  n?: number
  /** Container className */
  containerClassName?: string
}

export function SquircleImage({
  className,
  containerClassName,
  n = 5,
  ...props
}: SquircleImageProps) {
  return (
    <Squircle n={n} className={containerClassName}>
      <img className={cn("w-full h-full object-cover", className)} {...props} />
    </Squircle>
  )
}

/**
 * SquircleComparison - Side-by-side comparison of border-radius vs squircle
 */
export function SquircleComparison({
  className,
  children,
}: {
  className?: string
  children?: React.ReactNode
}) {
  return (
    <div className={cn("flex gap-8 items-center", className)}>
      {/* Regular border-radius */}
      <div className="flex flex-col items-center gap-2">
        <div className="w-24 h-24 bg-gradient-to-br from-slate-400 to-slate-600 rounded-[24px]">
          {children}
        </div>
        <span className="text-xs text-muted-foreground">border-radius</span>
      </div>

      {/* Squircle */}
      <div className="flex flex-col items-center gap-2">
        <Squircle className="w-24 h-24 bg-gradient-to-br from-blue-500 to-purple-600">
          {children}
        </Squircle>
        <span className="text-xs text-muted-foreground">squircle (n=5)</span>
      </div>
    </div>
  )
}

/**
 * Hook to generate superellipse path
 */
export function useSuperellipsePath(n: number = 5, size: number = 100): string {
  return React.useMemo(() => generateSuperellipsePath(n, size, 360), [n, size])
}

/**
 * Hook to check if CSS corner-shape is supported
 */
export function useCornerShapeSupport(): boolean {
  const [supported, setSupported] = React.useState(false)

  React.useEffect(() => {
    if (typeof CSS !== "undefined" && CSS.supports) {
      setSupported(CSS.supports("corner-shape", "squircle"))
    }
  }, [])

  return supported
}

// Export utilities for advanced usage
export {
  generateSuperellipsePath,
  generateSquirclePath,
  createSquircleSvgUrl,
  SQUIRCLE_PATH,
}
